WITH logs AS (SELECT if(mapContains(attributes_string, 'process.command_line'), attributes_string['process.command_line'], NULL) AS CommandLine, if(mapContains(attributes_string, 'process.executable'), attributes_string['process.executable'], NULL) AS Image FROM signoz_logs.distributed_logs_v2
WHERE timestamp >= {start_ns:UInt64} AND timestamp < {end_ns:UInt64}
AND resources_string['resource_id'] = {resource_id:String}
AND attributes_string['event.dataset'] = {dataset:String})
SELECT count() AS source_count, countIf(isNotNull(CommandLine) AND isNotNull(Image)) AS usable_count,
countIf(coalesce(((Image ILIKE '%/auditctl' AND CommandLine ILIKE '%-e 0%') OR (Image ILIKE '%/systemctl' AND CommandLine ILIKE '%stop auditd%')), false)) AS match_count FROM logs FORMAT JSON
